function art(color='#f4a683',name='luna',large=false){const hair=name==='marco'?'#392c2b':name==='tio'?'#583b24':'#4a302a',shirt=name==='marco'?'#74a4a0':name==='tio'?'#e79b50':'#f17856';return `<div class="cartoon" aria-hidden="true"><svg viewBox="0 0 100 110" role="img"><ellipse cx="50" cy="105" rx="33" ry="4" fill="#d9cdb6" opacity=".55"/><path d="M22 104c1-21 12-29 28-29s27 8 28 29" fill="${shirt}"/><path d="M30 46c-5-17 1-33 20-34 21-1 27 16 21 36l-3 15H31z" fill="${hair}"/><ellipse cx="50" cy="48" rx="24" ry="29" fill="${color}"/><path d="M26 40c0-23 13-34 28-31 13 2 21 12 20 27-7-2-12-9-15-16-9 10-19 14-33 14z" fill="${hair}"/><path d="M27 44c-4-4-8 0-5 7 2 5 5 6 8 5m43-12c4-4 8 0 5 7-2 5-5 6-8 5" fill="${color}"/><ellipse cx="41" cy="49" rx="2.3" ry="3" fill="#302921"/><ellipse cx="59" cy="49" rx="2.3" ry="3" fill="#302921"/><path d="M44 62q6 5 12 0" fill="none" stroke="#9b5345" stroke-width="2" stroke-linecap="round"/><circle cx="35" cy="57" r="3" fill="#ed8d82" opacity=".65"/><circle cx="65" cy="57" r="3" fill="#ed8d82" opacity=".65"/><path d="M41 79l9 9 9-9" fill="#fff6e8" opacity=".9"/><circle cx="50" cy="90" r="2" fill="#f8d265"/></svg></div>`}
const $=id=>document.getElementById(id);let saved={};try{saved=JSON.parse(localStorage.getItem('hola-game-v1')||'{}')}catch{};let state={current:Math.min(Number(saved.current)||0,lessons.length-1),filter:'all',done:new Set(saved.done||[]),xp:Number(saved.xp)||0,total:Number(saved.total)||0,correct:Number(saved.correct)||0,chatCount:0};
const levelNames={A0:'البداية',A1:'مبتدئ',A2:'ما قبل المتوسط',B1:'متوسط'};const levelColors={A0:'#ef9a65',A1:'#6caa7d',A2:'#7596c1',B1:'#9a7ab7'};const digits=n=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);
function persist(){localStorage.setItem('hola-game-v1',JSON.stringify({current:state.current,done:[...state.done],xp:state.xp,total:state.total,correct:state.correct}))}
function renderLevels(){const counts=['A0','A1','A2','B1'];$('levels').innerHTML=counts.map(l=>`<button class="level ${lessons[state.current].level===l?'active':''}" data-level="${l}"><span class="bubble">${l}</span>${levelNames[l]}<small>${lessons.filter(x=>x.level===l).length} دروس</small></button>`).join('');$('levels').querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.level;renderCards();renderNav();document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x.dataset.filter===state.filter))})}
function renderNav(){const l=lessons[state.current].level;$('lessonNav').innerHTML=lessons.filter(x=>x.level===l).map(x=>`<button class="lesson-link ${x.id===state.current?'active':''} ${state.done.has(x.id)?'done':''}" data-id="${x.id}"><span class="lesson-dot">${state.done.has(x.id)?'✓':digits(x.id+1)}</span>${x.title}</button>`).join('');$('lessonNav').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>selectLesson(+b.dataset.id))}
function renderFilters(){$('filters').innerHTML=[['all','كل المستويات'],['A0','A0 · البداية'],['A1','A1 · مبتدئ'],['A2','A2 · ما قبل المتوسط'],['B1','B1 · متوسط']].map(([v,n])=>`<button class="filter ${state.filter===v?'active':''}" data-filter="${v}">${n}</button>`).join('');$('filters').querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;renderCards();document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x.dataset.filter===state.filter))})}
function renderCards(){const visible=lessons.filter(x=>state.filter==='all'||x.level===state.filter);$('lessonCards').innerHTML=visible.map(x=>`<button class="lesson-card ${x.id===state.current?'selected':''}" data-id="${x.id}"><div class="card-top"><span class="level-tag" style="color:${levelColors[x.level]};background:${levelColors[x.level]}18">${x.level} · ${levelNames[x.level]}</span><span class="card-number">${state.done.has(x.id)?'✓ مكتمل':digits(x.id+1)+' / ١٢'}</span></div><h3>${x.title}</h3><p>${x.topic} · ${x.character}</p><div class="mini-progress"><span style="width:${state.done.has(x.id)?100:0}%"></span></div></button>`).join('');$('lessonCards').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>selectLesson(+b.dataset.id))}
function renderStats(){$('xp').textContent=digits(state.xp);$('completed').textContent=`${digits(state.done.size)} / ١٢`;$('accuracy').textContent=state.total?`${Math.round(state.correct/state.total*100)}٪`:'—';$('streak').textContent=digits(Number(saved.streak)||1)}
function addBubble(text,translation){const b=document.createElement('div');b.className='character-bubble';b.innerHTML=`${art(lessons[state.current].color,lessons[state.current].character==='ماركو'?'marco':lessons[state.current].character==='تيّو'?'tio':'luna')}<div class="bubble-text"><b dir="ltr">${escapeHTML(text)}</b>${translation?`<em>${escapeHTML(translation)}</em>`:''}</div>`;$('chat').appendChild(b);$('chat').scrollTop=$('chat').scrollHeight}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderLesson(){const x=lessons[state.current],isMarco=x.character==='ماركو',isTio=x.character==='تيّو';$('lessonTitle').textContent=x.title;$('lessonDescription').textContent=x.prompt;$('missionTag').textContent=`● ${x.level} · ${x.topic}`;$('characterName').textContent=x.character;$('characterRole').textContent=x.role;$('chatAvatar').innerHTML=art(x.color,isMarco?'marco':isTio?'tio':'luna');$('heroArt').innerHTML=art(x.color,isMarco?'marco':isTio?'tio':'luna');$('chat').innerHTML='';addBubble(x.intro,x.translation);$('question').textContent=x.question;$('taskSub').textContent=x.sub;$('taskNumber').textContent=digits(x.id+1);$('feedback').textContent='';$('answers').innerHTML=x.options.map((op,i)=>`<button class="answer" data-answer="${i}">${op}</button>`).join('');$('answers').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));$('quickPhrases').innerHTML=x.phrases.map(p=>`<button class="phrase" data-phrase="${escapeHTML(p)}">${p}</button>`).join('');$('quickPhrases').querySelectorAll('[data-phrase]').forEach(b=>b.onclick=()=>sendMessage(b.dataset.phrase));$('chatInput').value='';$('chatInput').placeholder=x.prompt;$('chatInput').dir='auto';$('sayAgain').onclick=()=>speak(x.intro);renderCards();renderNav();renderLevels();renderStats()}
function selectLesson(id){state.current=id;persist();renderLesson();if(innerWidth<760)$('practice').scrollIntoView({behavior:'smooth',block:'start'})}
function answer(index){const x=lessons[state.current];state.total++;const btns=[...$('answers').querySelectorAll('.answer')];btns.forEach((b,i)=>{b.disabled=true;if(i===x.correct)b.classList.add('correct')});if(index===x.correct){state.correct++;$('feedback').textContent=state.done.has(x.id)?'¡Muy bien! إجابة صحيحة — هذا الدرس مكتمل بالفعل.':'¡Muy bien! إجابة صحيحة! +١٥ نقطة ⭐';if(!state.done.has(x.id)){state.done.add(x.id);state.xp+=15}playTone(true)}else{btns[index].classList.add('wrong');$('feedback').textContent=`قريب! الإجابة هي: ${x.options[x.correct]} — حاول قولها بصوت عالٍ.`;playTone(false)}persist();renderStats();renderCards();renderNav()}
function sendMessage(raw){const text=raw.trim();if(!text)return;const b=document.createElement('div');b.className='player-bubble';b.setAttribute('dir','auto');b.textContent=text;$('chat').appendChild(b);$('chat').scrollTop=$('chat').scrollHeight;$('chatInput').value='';const x=lessons[state.current];const response=['¡Muy bien! 🌟','¡Qué bien! نستمرّ خطوة أخرى.','¡Excelente! لقد فهمت ما تقصد.'][state.chatCount++%3];setTimeout(()=>{addBubble(response,'استمرّ بالمحاولة، أنت تتقدّم!');if(state.chatCount===1)speak(response);},280);}
$('sendBtn').onclick=()=>sendMessage($('chatInput').value);$('chatInput').addEventListener('keydown',e=>{if(e.key==='Enter')sendMessage(e.currentTarget.value)});$('nextBtn').onclick=()=>selectLesson((state.current+1)%lessons.length);$('startBtn').onclick=()=>$('practice').scrollIntoView({behavior:'smooth',block:'center'});$('allLessons').onclick=()=>{state.filter='all';renderFilters();renderCards()};
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function speak(text){if(!('speechSynthesis'in window)){toast('ميزة النطق غير متاحة في هذا المتصفح. يمكنك متابعة القراءة والكتابة.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='es-ES';u.rate=.88;const voices=speechSynthesis.getVoices();const v=voices.find(a=>a.lang.toLowerCase().startsWith('es'));if(v)u.voice=v;speechSynthesis.speak(u)}
function playTone(ok){try{const c=new(window.AudioContext||window.webkitAudioContext)(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=ok?660:220;g.gain.setValueAtTime(.08,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.16);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.16)}catch{}}
let recognition=null;function startLocalVoice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR||!('processLocally'in SR.prototype)){toast('لضمان الخصوصية والعمل دون إنترنت، التعرّف الصوتي يحتاج متصفحًا يدعم حزمة إسبانية محلية. اكتب إجابتك أو اختر عبارة جاهزة.');return}try{recognition=new SR();recognition.lang='es-ES';recognition.processLocally=true;recognition.interimResults=false;recognition.maxAlternatives=1;$('micBtn').classList.add('listening');toast('¡Te escucho! تكلّم بالإسبانية…');recognition.onresult=e=>{const phrase=e.results[0][0].transcript;$('chatInput').value=phrase;sendMessage(phrase)};recognition.onerror=e=>{const message=e.error==='language-not-supported'?'حزمة التعرّف الإسبانية المحلية غير مثبتة. استخدم الكتابة أو العبارات الجاهزة.':'تعذّر بدء الميكروفون محليًا. يمكنك الكتابة بدلًا من ذلك.';toast(message)};recognition.onend=()=>$('micBtn').classList.remove('listening');recognition.start()}catch{ $('micBtn').classList.remove('listening');toast('التعرّف المحلي غير متاح الآن. اكتب إجابتك أو اختر عبارة جاهزة.') }}$('micBtn').onclick=startLocalVoice;
renderFilters();renderLesson();
</script></body></html>

